export const LIMITS={battery:30,thermalMargin:4,deltaV:8,operatorMinutes:0};
export const RESOURCE_NAMES={battery:'Battery',thermalMargin:'Thermal margin',deltaV:'Manoeuvre reserve',operatorMinutes:'Operator attention'};
const clone=x=>JSON.parse(JSON.stringify(x));
const round=n=>Math.round(n*1000)/1000;
export function initialMission(c){return {schema:2,caseId:'atlas-r8.1',scenarioId:c.scenario?.id||'standard',...clone(c.initial),stage:0,time:0,history:[],samples:[],pending:[],events:[],breaches:[],arguments:{},ended:false}}
export function snapshot(s){return {time:s.time,battery:s.battery,thermalMargin:s.thermalMargin,deltaV:s.deltaV,operatorMinutes:s.operatorMinutes,groundContact:s.groundContact,telemetryFresh:s.telemetryFresh,flags:[...s.flags],evidence:[...s.evidence],dataValue:s.dataValue}}
function apply(s,e){for(let [k,v] of Object.entries(e.effects||{}))s[k]=round(s[k]+v);s.battery=Math.min(100,s.battery);s.evidenceCoverage=Math.min(100,s.evidenceCoverage);s.dataValue=Math.max(0,s.dataValue);if(e.set)Object.assign(s,e.set);for(let f of e.addFlags||[])if(!s.flags.includes(f))s.flags.push(f);for(let id of e.addEvidence||[])if(!s.evidence.includes(id))s.evidence.push(id)}
function checkLimits(s){for(let[k,v]of Object.entries(LIMITS))if(s[k]<v&&!s.breaches.some(b=>b.resource===k)){s.breaches.push({resource:k,time:s.time,value:s[k],floor:v});if(!s.flags.includes('releaseHeld'))s.flags.push('releaseHeld')}}
function advance(c,s,to){for(let minute=s.time+1;minute<=to;minute++){s.time=minute;let shadow=minute>32&&minute<=62;s.battery=round(Math.min(100,s.battery+(shadow?c.baseline.perElapsedMinute.batteryEclipse:c.baseline.perElapsedMinute.batterySun)));s.thermalMargin=round(s.thermalMargin+(shadow?c.baseline.perElapsedMinute.thermalEclipse:c.baseline.perElapsedMinute.thermalSun));for(let event of s.pending.filter(e=>!e.applied&&e.at<=minute)){apply(s,event);event.applied=true;s.events.push({time:minute,text:event.text,effects:event.effects||{},evidence:event.addEvidence||[]})}checkLimits(s);s.samples.push(snapshot(s))}}
function move(c,state,choice){let s=clone(state),before=snapshot(s);apply(s,choice);for(let e of choice.delayed||[])s.pending.push({...clone(e),applied:false});checkLimits(s);s.samples.push(snapshot(s));let next=s.stage+1,target=c.stages[next]?.minute??96;advance(c,s,target);s.stage=next;s.ended=next>=c.stages.length;if(!s.ended&&c.stages[next].entry)Object.assign(s,c.stages[next].entry);if(!s.ended&&c.stages[next].entry)s.samples.push(snapshot(s));let after=snapshot(s);s.history.push({stage:state.stage,time:state.time,to:target,title:c.stages[state.stage].title,choice:choice.id,label:choice.title,effects:clone(choice.effects||{}),delayed:clone(choice.delayed||[]),coaching:choice.coaching,before,after});return s}
export function availability(c,s,o){if(s.ended)return 'This run has ended. Start a new run to make another decision.';if(o.unavailable)return o.unavailable;let r=o.requires||{},problems=[];for(let[k,field]of Object.entries({batteryAtLeast:'battery',thermalMarginAtLeast:'thermalMargin',deltaVAtLeast:'deltaV',operatorMinutesAtLeast:'operatorMinutes'}))if(r[k]!==undefined&&s[field]<r[k])problems.push(`${RESOURCE_NAMES[field]} needs ${r[k]}; current ${s[field].toFixed(1)}`);for(let f of ['groundContact','telemetryFresh'])if(r[f]===true&&!s[f])problems.push(f==='groundContact'?'No current ground contact':'Fresh telemetry is missing');for(let e of r.allEvidence||[])if(!s.evidence.includes(e))problems.push(`Evidence ${e} is missing`);for(let f of r.notFlags||[])if(s.flags.includes(f))problems.push('The new release is already held');if(problems.length)return problems.join('. ')+'.';let next=move(c,s,o);let breach=next.breaches.find(b=>!s.breaches.some(old=>old.resource===b.resource));if(breach)return `${RESOURCE_NAMES[breach.resource]} would cross the case floor at T+${breach.time}, before the next decision.`;for(let k of Object.keys(LIMITS)){if(next[k]<LIMITS[k])return `${RESOURCE_NAMES[k]} would fall below the case limit (${LIMITS[k]}) by the next decision.`}return null}
export function forecast(c,s,id){let o=c.stages[s.stage]?.choices.find(x=>x.id===id);if(!o)throw new Error('Unknown decision');return {reason:availability(c,s,o),next:move(c,s,o),choice:o}}
export function commitChoice(c,s,id){let o=c.stages[s.stage]?.choices.find(x=>x.id===id);if(!o)throw new Error('Unknown decision');let reason=availability(c,s,o);if(reason)throw new Error(reason);return move(c,s,o)}
export function emergencyHandover(c,s){if(s.ended)return clone(s);let n=clone(s),before=snapshot(n);n.flags.push('releaseHeld','externalDeskOwner','attentionShortfall');n.events.push({time:n.time,text:'Candidate trial stopped. Existing duty flight authority receives an attention-shortfall alert and assumes the mission; event closure is not asserted.',effects:{}});n.ended=true;n.samples.push(snapshot(n));n.history.push({stage:n.stage,time:n.time,to:n.time,title:c.stages[n.stage].title,choice:'stop',label:'Stop candidate trial and transfer to duty authority',effects:{},delayed:[],coaching:'You preserve the authority boundary and explicitly transfer unresolved obligations. This is a constrained outcome, not a completed pass.',before,after:snapshot(n)});return n}
export function frameAt(s,time){const series=s.samples.length?s.samples:[snapshot(s)],t=Math.max(0,Math.min(s.time,time));let left=series[0],right=series[series.length-1];for(let p of series){if(p.time<=t)left=p;else{right=p;break}}let f=right.time>left.time?(t-left.time)/(right.time-left.time):0,r={...left,time:t};for(let k of Object.keys(LIMITS))r[k]=left[k]+(right[k]-left[k])*f;r.safe=r.flags.includes('safeHold');r.burn=s.history.some(x=>x.choice==='manual-burn'&&t>=x.time&&t<x.time+2);return r}
export function missionOutcome(s){if(!s.ended)return {title:'Mission in progress',kind:'active'};if(s.flags.includes('handoverGap')||s.flags.includes('attentionShortfall'))return {title:'Unassured handover',kind:'alert'};if(s.flags.includes('limitedContinuation')&&!s.flags.includes('releaseHeld')&&s.evidence.includes('E6'))return {title:'Bounded continuation supported',kind:'success'};if(s.flags.includes('limitedContinuation')&&s.flags.includes('packDeferred'))return {title:'Continuation with an open assurance gap',kind:'alert'};return {title:'Release held · baseline retained',kind:'hold'}}
export function reviewArgument(s,a){let rows=[],add=(status,title,detail)=>rows.push({status,title,detail}),cont=a.recommendation==='continue',held=a.recommendation==='hold',needs=['E0','E2','E4','E5','E6'];
 if(!a.recommendation)add('missing','Recommendation','Choose an explicit recommendation.');else if(a.recommendation==='fleet')add('contradicted','Authority fit','Your fleet claim conflicts with E0: R8.1 permits advisory use on ATLAS–01 only.');else if(cont&&missionOutcome(s).kind!=='success')add('contradicted','Outcome fit',`You claim continuation, but your ledger concludes “${missionOutcome(s).title}”. Close or explicitly hold the observed gaps.`);else add('supported','Authority fit',held?'You withhold the candidate release and retain the existing baseline.':'Your recommendation matches the bounded advisory outcome.');
 let cited=a.evidence||[],invalid=cited.filter(id=>!s.evidence.includes(id)||id.startsWith('X'));
 if(!cited.length)add('missing','Evidence applicability','Cite the records you actually assembled.');else if(invalid.length)add('contradicted','Evidence applicability',`${invalid.join(', ')} ${invalid.length===1?'is':'are'} unavailable or inapplicable in this run. A record title is not proof that you obtained it.`);else if(cont&&needs.some(id=>!cited.includes(id)))add('missing','Evidence applicability',`Continuation needs current scoped records: ${needs.filter(id=>!cited.includes(id)).join(', ')}.`);else add('supported','Evidence applicability',`${cited.join(', ')} are present in this run and support a scoped argument.`);
 let entry=s.history[Number(a.event)],metric=a.tradeoff,total=entry?(entry.effects?.[metric]||0)+(entry.delayed||[]).reduce((n,e)=>n+(e.effects?.[metric]||0),0):0;
 if(!metric||a.event===undefined||a.event==='')add('missing','Causal trade-off','Select a resource and the actual decision that changed it.');else if(!total)add('contradicted','Causal trade-off',`“${entry?.label||'Selected event'}” has no authored ${RESOURCE_NAMES[metric]||metric} effect. Choose a ledger event that supports your claimed trade-off.`);else add('supported','Causal trade-off',`“${entry.label}” changes ${RESOURCE_NAMES[metric]||metric} by ${total>0?'+':''}${total}, including scheduled effects. The ledger supports this causal claim.`);
 let threshold=Number(a.threshold),floor=LIMITS[a.stopMetric];
 if(!a.stopMetric||a.threshold===''||a.threshold===undefined)add('missing','Measurable stop','Name a monitored resource and a threshold.');else if(!Number.isFinite(threshold)||threshold<floor)add('contradicted','Measurable stop',`Your threshold (${a.threshold}) permits crossing the case floor of ${floor}. Set a threshold at least as conservative as that floor.`);else if(threshold>s[a.stopMetric]&&held)add('supported','Measurable stop',`The current ${RESOURCE_NAMES[a.stopMetric]} is already below ${threshold}; your hold recommendation obeys that stop condition.`);else if(threshold>s[a.stopMetric])add('contradicted','Measurable stop',`The current ${RESOURCE_NAMES[a.stopMetric]} is ${s[a.stopMetric].toFixed(1)}, already below your ${threshold} threshold. A continuation claim must therefore be withheld now.`);else add('supported','Measurable stop',`Halt candidate use if ${RESOURCE_NAMES[a.stopMetric]} falls below ${threshold}; this precedes or matches the case limit (${floor}).`);
 if(!a.owner)add('missing','Accountable owner','Name the authority who can stop candidate use.');else if(a.owner!=='flight')add('contradicted','Accountable owner','The model or vendor does not own flight authority. The duty flight director must own the stop and handover.');else add('supported','Accountable owner','The duty flight director owns the stop and unresolved obligations.');
 let gap=s.flags.includes('externalDeskOwner')?'conjunction':!s.evidence.includes('E6')?'handover':!s.evidence.includes('E2')?'shadow':'transfer';if(!a.next)add('missing','Next evidence task','Name the evidence task that must precede expanded trust.');else if(a.next!==gap)add('contradicted','Next evidence task',`The first remaining obligation is ${gap==='conjunction'?'the unresolved conjunction record':gap==='handover'?'the integrated handover pack':gap==='shadow'?'current-build shadow evidence':'longer-duration shadow and transfer evidence'}. Your selected task does not close that gap.`);else add('supported','Next evidence task','Your next task addresses the first material gap in this run.');
 if(a.expiry!=='nextpass')add(a.expiry?'contradicted':'missing','Expiry','This pass ends at T+96. Renewal is required before the next pass and whenever the build or operating regime changes.');else add('supported','Expiry','The claim expires before the next pass and reopens on configuration changes.');return rows}
